window.__TNPSC_REGISTER_TEST__("gk", 9, [{"id":801,"subject":"gk","testNumber":9,"question":"'பொருளியலின் தந்தை' என அழைக்கப்படும் அறிஞர் யார்?","options":["ஜான் மேனார்ட் கீன்ஸ்","லயனல் ராபின்ஸ்","ஆடம் ஸ்மித்","ஆல்பிரட் மார்ஷல்"],"correctAnswer":2,"explanation":"ஸ்காட்லாந்து நாட்டைச் சேர்ந்த ஆடம் ஸ்மித் 'பொருளியலின் தந்தை' என அழைக்கப்படுகிறார். இவர் 1776ஆம் ஆண்டு எழுதிய 'நாடுகளின் செல்வம்' என்ற நூல் பொருளியலைத் தனி அறிவியலாக நிறுவியது. இவர் பொருளியலைச் 'செல்வத்தைப் பற்றிய அறிவியல்' என வரையறுத்தார்.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":802,"subject":"gk","testNumber":9,"question":"ஆடம் ஸ்மித்தின் 'நாடுகளின் செல்வத்தின் இயல்பும் காரணங்களும் பற்றிய ஓர் ஆய்வு' (The Wealth of Nations) என்ற நூல் எந்த ஆண்டு வெளியிடப்பட்டது?","options":["1789","1890","1936","1776"],"correctAnswer":3,"explanation":"ஆடம் ஸ்மித் எழுதிய 'நாடுகளின் செல்வத்தின் இயல்பும் காரணங்களும் பற்றிய ஓர் ஆய்வு' என்ற புகழ்பெற்ற நூல் 1776ஆம் ஆண்டு வெளியிடப்பட்டது. இந்த நூலில் வேலைப் பகுப்பு முறை மற்றும் தலையிடாக் கொள்கை போன்ற அடிப்படைப் பொருளியல் கருத்துகள் விளக்கப்பட்டுள்ளன.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":803,"subject":"gk","testNumber":9,"question":"பொருளியலுக்கு 'நல இலக்கணம்' (Welfare Definition) வகுத்து, 'பொருளியல் கோட்பாடுகள்' என்ற நூலை 1890ஆம் ஆண்டு வெளியிட்டவர் யார்?","options":["ஆல்பிரட் மார்ஷல்","டேவிட் ரிக்கார்டோ","ஜே.பி. சே","பால் சாமுவேல்சன்"],"correctAnswer":0,"explanation":"ஆல்பிரட் மார்ஷல் 1890ஆம் ஆண்டு வெளியிட்ட 'பொருளியல் கோட்பாடுகள்' (Principles of Economics) என்ற நூலில் நல இலக்கணத்தைக் கூறினார். இதன்படி, பொருளியல் என்பது மனிதனின் அன்றாட வாழ்க்கை நடவடிக்கைகளையும், அவனது நலனை மேம்படுத்தும் செல்வப் பயன்பாட்டையும் ஆராயும் இயலாகும்.","difficulty":"medium","topic":"பொருளாதார அடிப்படைகள்"},{"id":804,"subject":"gk","testNumber":9,"question":"பொருளியலின் 'பற்றாக்குறை இலக்கணத்தை' (Scarcity Definition) 1932ஆம் ஆண்டு முன்வைத்த பொருளியல் அறிஞர் யார்?","options":["லயனல் ராபின்ஸ்","ஆல்பிரட் மார்ஷல்","ஆடம் ஸ்மித்","பால் சாமுவேல்சன்"],"correctAnswer":0,"explanation":"லயனல் ராபின்ஸ் 1932ஆம் ஆண்டு 'பொருளியல் அறிவியலின் இயல்பும் சிறப்பும் பற்றிய ஒரு கட்டுரை' என்ற நூலில் பற்றாக்குறை இலக்கணத்தை வெளியிட்டார். எல்லையற்ற மனித விருப்பங்களையும், மாற்றுப் பயன்பாடுடைய பற்றாக்குறை வளங்களையும் தொடர்புபடுத்தும் அறிவியலே பொருளியல் என்பது இவரது கருத்தாகும்.","difficulty":"medium","topic":"பொருளாதார அடிப்படைகள்"},{"id":805,"subject":"gk","testNumber":9,"question":"'நுண்ணியல் பொருளியல்' (Micro Economics) மற்றும் 'பேரியல் பொருளியல்' (Macro Economics) என்ற சொற்களை 1933ஆம் ஆண்டு முதன்முதலில் உருவாக்கியவர் யார்?","options":["மில்டன் ஃப்ரீட்மேன்","கார்ல் மார்க்ஸ்","ராக்னர் ஃபிரிஷ்","ஜான் மேனார்ட் கீன்ஸ்"],"correctAnswer":2,"explanation":"நார்வே நாட்டைச் சேர்ந்த பொருளியல் அறிஞர் ராக்னர் ஃபிரிஷ் 1933ஆம் ஆண்டு நுண்ணியல் பொருளியல் மற்றும் பேரியல் பொருளியல் என்ற இரு சொற்களை அறிமுகப்படுத்தினார். இவர் பொருளியலுக்கான முதல் நோபல் பரிசை 1969ஆம் ஆண்டு பெற்றவர்களில் ஒருவர் ஆவார்.","difficulty":"hard","topic":"பொருளாதார அடிப்படைகள்"},{"id":806,"subject":"gk","testNumber":9,"question":"வேளாண்மை, மீன்பிடித்தல், காடு வளர்ப்பு மற்றும் சுரங்கத் தொழில் ஆகியவை பொருளாதாரத்தின் எந்தத் துறையின் கீழ் வகைப்படுத்தப்படுகின்றன?","options":["முதன்மைத் துறை","நான்காம் துறை","மூன்றாம் துறை","இரண்டாம் துறை"],"correctAnswer":0,"explanation":"இயற்கை வளங்களை நேரடியாகப் பயன்படுத்தி மூலப்பொருள்களை உற்பத்தி செய்யும் வேளாண்மை, மீன்பிடித்தல், கால்நடை வளர்ப்பு, காடு வளர்ப்பு மற்றும் சுரங்கத் தொழில் ஆகியவை முதன்மைத் துறை (Primary Sector) எனப்படும். இந்திய மக்கள் தொகையில் பெரும் பகுதியினர் இன்றும் இத்துறையைச் சார்ந்துள்ளனர்.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":807,"subject":"gk","testNumber":9,"question":"இந்தியாவின் மொத்த உள்நாட்டு உற்பத்தியில் (GDP) மிக அதிக அளவு பங்களிப்பை வழங்கும் பொருளாதாரத் துறை எது?","options":["முதன்மைத் துறை","மூன்றாம் துறை (சேவைத் துறை)","இரண்டாம் துறை","சுரங்கத் துறை"],"correctAnswer":1,"explanation":"வங்கி, காப்பீடு, போக்குவரத்து, தகவல் தொழில்நுட்பம், கல்வி மற்றும் சுகாதாரம் ஆகியவற்றை உள்ளடக்கிய மூன்றாம் துறையான சேவைத் துறை இந்தியாவின் மொத்த உள்நாட்டு உற்பத்தியில் மிக அதிக பங்களிப்பை (50% க்கும் மேல்) வழங்குகிறது. ஆனால் வேலைவாய்ப்பில் முதன்மைத் துறை முன்னிலையில் உள்ளது.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":808,"subject":"gk","testNumber":9,"question":"பொதுத்துறையும் தனியார்துறையும் இணைந்து பொருளாதார நடவடிக்கைகளில் ஈடுபடும் அமைப்பு எவ்வாறு அழைக்கப்படுகிறது?","options":["சமத்துவப் பொருளாதாரம்","தன்னிறைவுப் பொருளாதாரம்","முதலாளித்துவப் பொருளாதாரம்","கலப்புப் பொருளாதாரம்"],"correctAnswer":3,"explanation":"பொதுத்துறையும் தனியார்துறையும் இணைந்து செயல்படும் பொருளாதார அமைப்பு 'கலப்புப் பொருளாதாரம்' (Mixed Economy) எனப்படும். இதில் சமூக நலனும் தனியார் லாப நோக்கமும் சமநிலையில் பேணப்படுகின்றன; இந்தியா கலப்புப் பொருளாதாரத்திற்குச் சிறந்த எடுத்துக்காட்டாகும்.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":809,"subject":"gk","testNumber":9,"question":"தேவை விதியின்படி (Law of Demand), பிற காரணிகள் மாறாமல் இருக்கும்போது ஒரு பொருளின் விலை அதிகரித்தால் அதன் தேவை எவ்வாறு மாறும்?","options":["குறையும்","மாறாமல் இருக்கும்","இருமடங்காகும்","அதிகரிக்கும்"],"correctAnswer":0,"explanation":"தேவை விதியின்படி, பிற காரணிகள் மாறாமல் இருக்கும்போது ஒரு பொருளின் விலை உயர்ந்தால் அதன் தேவை குறையும்; விலை குறைந்தால் அதன் தேவை அதிகரிக்கும். அதாவது ஒரு பொருளின் விலையும் தேவையும் எதிர்மறைத் தொடர்பைக் கொண்டுள்ளன.","difficulty":"easy","topic":"பொருளாதார அடிப்படைகள்"},{"id":810,"subject":"gk","testNumber":9,"question":"தேவை விதிக்கு விதிவிலக்காக, விலை குறையும்போது தேவையும் குறைந்து, விலை உயரும்போது தேவையும் உயரும் தாழ்ந்த ரகப் பொருள்கள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["நுகர்வுப் பொருள்கள்","ஆடம்பரப் பொருள்கள்","மூலதனப் பொருள்கள்","கிஃபன் பொருள்கள்"],"correctAnswer":3,"explanation":"சர் ராபர்ட் கிஃபன் கண்டறிந்த முரண்பாட்டின்படி, சில தாழ்ந்த ரக அத்தியாவசியப் பொருள்களின் விலை குறையும்போது அவற்றின் தேவை குறைவதும், விலை உயரும்போது தேவை அதிகரிப்பதும் 'கிஃபன் பொருள்கள்' (Giffen Goods) எனப்படும். இவை தேவை விதிக்கு முக்கிய விதிவிலக்காகும்.","difficulty":"hard","topic":"பொருளாதார அடிப்படைகள்"},{"id":811,"subject":"gk","testNumber":9,"question":"அளிப்பு விதியின்படி (Law of Supply), பிற காரணிகள் மாறாமல் இருக்கும்போது ஒரு பொருளின் விலைக்கும் அதன் அளிப்பிற்கும் இடையே உள்ள தொடர்பு எத்தகையது?","options":["தொடர்பு இல்லை","நெகிழ்ச்சியற்ற தொடர்பு","நேர்மறைத் தொடர்பு","எதிர்மறைத் தொடர்பு"],"correctAnswer":2,"explanation":"அளிப்பு விதியின்படி, பிற காரணிகள் மாறாமல் இருக்கும்போது ஒரு பொருளின் விலை உயர்ந்தால் அதன் அளிப்பும் உயரும்; விலை குறைந்தால் அளிப்பும் குறையும். எனவே விலைக்கும் அளிப்பிற்கும் இடையே நேர்மறைத் தொடர்பு உள்ளது.","difficulty":"medium","topic":"பொருளாதார அடிப்படைகள்"},{"id":812,"subject":"gk","testNumber":9,"question":"ஒரு நாட்டின் புவியியல் எல்லைக்குள் ஓர் ஆண்டில் உற்பத்தி செய்யப்படும் அனைத்து இறுதிப் பண்டங்கள் மற்றும் பணிகளின் மொத்தப் பண மதிப்பு எவ்வாறு அழைக்கப்படுகிறது?","options":["மொத்த நாட்டு உற்பத்தி (GNP)","மொத்த உள்நாட்டு உற்பத்தி (GDP)","நிகர நாட்டு உற்பத்தி (NNP)","தனிநபர் வருமானம் (PI)"],"correctAnswer":1,"explanation":"ஒரு நாட்டின் புவியியல் எல்லைக்குள் ஒரு குறிப்பிட்ட நிதியாண்டில் உற்பத்தி செய்யப்படும் இறுதிப் பண்டங்கள் மற்றும் பணிகளின் மொத்த அங்காடி மதிப்பு 'மொத்த உள்நாட்டு உற்பத்தி' (GDP) எனப்படும். இது ஒரு நாட்டின் பொருளாதார வளர்ச்சியை அளவிடும் முதன்மைக் குறியீடாகும்.","difficulty":"easy","topic":"தேசிய வருமானம்"},{"id":813,"subject":"gk","testNumber":9,"question":"மொத்த நாட்டு உற்பத்திக்கும் (GNP) மொத்த உள்நாட்டு உற்பத்திக்கும் (GDP) இடையே உள்ள வேறுபாட்டைக் குறிப்பது எது?","options":["மூலதனத் தேய்மானம்","அரசு மானியங்கள்","மறைமுக வரிகள்","வெளிநாட்டிலிருந்து கிடைக்கும் நிகர காரணி வருமானம் (NFIA)"],"correctAnswer":3,"explanation":"மொத்த உள்நாட்டு உற்பத்தியுடன் (GDP) வெளிநாட்டிலிருந்து கிடைக்கும் நிகர காரணி வருமானத்தைக் (NFIA = X - M) கூட்டினால் மொத்த நாட்டு உற்பத்தி (GNP) கிடைக்கும். அதாவது GNP = GDP + வெளிநாட்டிலிருந்து கிடைக்கும் நிகர காரணி வருமானம் ஆகும்.","difficulty":"medium","topic":"தேசிய வருமானம்"},{"id":814,"subject":"gk","testNumber":9,"question":"நிகர நாட்டு உற்பத்தி (NNP) கீழ்க்கண்ட எந்தச் சூத்திரத்தின் மூலம் கணக்கிடப்படுகிறது?","options":["GDP + தேய்மானம்","GNP + மறைமுக வரி","GDP - வெளிநாட்டு வருமானம்","GNP - தேய்மானம்"],"correctAnswer":3,"explanation":"மொத்த நாட்டு உற்பத்தியிலிருந்து (GNP) மூலதனப் பொருள்களின் தேய்மான மதிப்பைக் (Depreciation) கழித்தால் நிகர நாட்டு உற்பத்தி (NNP) கிடைக்கும். அதாவது NNP = GNP - தேய்மானம் ஆகும்.","difficulty":"medium","topic":"தேசிய வருமானம்"},{"id":815,"subject":"gk","testNumber":9,"question":"பொருளியலில் 'தேசிய வருமானம்' (National Income) என்று துல்லியமாகக் குறிப்பிடப்படுவது கீழ்க்கண்டவற்றுள் எது?","options":["தனிநபர் செலவிடக்கூடிய வருமானம்","அங்காடி விலையில் மொத்த நாட்டு உற்பத்தி","காரணிச் செலவில் நிகர நாட்டு உற்பத்தி (NNP at Factor Cost)","அங்காடி விலையில் மொத்த உள்நாட்டு உற்பத்தி"],"correctAnswer":2,"explanation":"அங்காடி விலையில் நிகர நாட்டு உற்பத்தியிலிருந்து மறைமுக வரிகளைக் கழித்து, மானியங்களைக் கூட்டினால் 'காரணிச் செலவில் நிகர நாட்டு உற்பத்தி' (NNP at Factor Cost) கிடைக்கும். இதுவே உண்மையான தேசிய வருமானம் எனக் கணக்கிடப்படுகிறது.","difficulty":"hard","topic":"தேசிய வருமானம்"},{"id":816,"subject":"gk","testNumber":9,"question":"ஒரு நாட்டின் தலா வருமானம் (Per Capita Income) எவ்வாறு கணக்கிடப்படுகிறது?","options":["தேசிய வருமானம் × மொத்த மக்கள் தொகை","மொத்த மக்கள் தொகை ÷ தேசிய வருமானம்","தேசிய வருமானம் - வரி வருவாய்","தேசிய வருமானம் ÷ மொத்த மக்கள் தொகை"],"correctAnswer":3,"explanation":"ஒரு நாட்டின் மொத்தத் தேசிய வருமானத்தை அந்நாட்டின் மொத்த மக்கள் தொகையால் வகுப்பதன் மூலம் தலா வருமானம் (தனிநபர் சராசரி வருமானம்) கணக்கிடப்படுகிறது. இது ஒரு நாட்டு மக்களின் சராசரி வாழ்க்கைத் தரத்தை அளவிட உதவுகிறது.","difficulty":"easy","topic":"தேசிய வருமானம்"},{"id":817,"subject":"gk","testNumber":9,"question":"இந்தியாவில் முதன்முதலாகத் தேசிய வருமானத்தைக் கணக்கிட்டுத் தனது 'வறுமையும் இந்தியாவில் பிரிட்டிஷ் ஆட்சியும்' என்ற நூலில் வெளியிட்டவர் யார்?","options":["வி.கே.ஆர்.வி. ராவ்","தாதாபாய் நௌரோஜி","பி.சி. மஹலனோபிஸ்","ஆர்.சி. தத்"],"correctAnswer":1,"explanation":"இந்தியாவின் முதுபெரும் மனிதர் தாதாபாய் நௌரோஜி 1867–68ஆம் ஆண்டில் முதன்முதலாக இந்தியாவின் தேசிய வருமானத்தைக் கணக்கிட்டார். அப்போது இந்தியரின் தலா வருமானம் ₹20 என இவர் தனது 'வறுமையும் இந்தியாவில் பிரிட்டிஷ் ஆட்சியும்' என்ற நூலில் குறிப்பிட்டார்.","difficulty":"medium","topic":"தேசிய வருமானம்"},{"id":818,"subject":"gk","testNumber":9,"question":"இந்தியாவில் அறிவியல் பூர்வமான முறையைப் பயன்படுத்தி முதன்முதலாக 1931–32ஆம் ஆண்டில் தேசிய வருமானத்தைக் கணக்கிட்டவர் யார்?","options":["டாக்டர் வி.கே.ஆர்.வி. ராவ்","தாதாபாய் நௌரோஜி","சி.என். வக்கீல்","டி.ஆர். காட்கில்"],"correctAnswer":0,"explanation":"டாக்டர் வி.கே.ஆர்.வி. ராவ் 1931–32ஆம் ஆண்டில் உற்பத்தி முறை மற்றும் வருமான முறை ஆகியவற்றை இணைத்து அறிவியல் பூர்வமாக இந்தியாவின் தேசிய வருமானத்தை முதன்முதலில் கணக்கிட்டார். அப்போது இந்தியாவின் தலா வருமானம் ₹62 எனக் கணக்கிடப்பட்டது.","difficulty":"hard","topic":"தேசிய வருமானம்"},{"id":819,"subject":"gk","testNumber":9,"question":"இந்தியாவில் தேசிய வருமானத்தை அதிகாரப்பூர்வமாகக் கணக்கிட்டு வெளியிடும் நிறுவனம் எது?","options":["இந்தியத் தணிக்கைத் துறை (CAG)","இந்திய ரிசர்வ் வங்கி (RBI)","மத்திய புள்ளியியல் அலுவலகம் (CSO / NSO)","நிதி ஆணையம்"],"correctAnswer":2,"explanation":"1951ஆம் ஆண்டு நிறுவப்பட்ட மத்திய புள்ளியியல் அலுவலகம் (CSO) இந்தியாவின் தேசிய வருமானத்தை அதிகாரப்பூர்வமாகக் கணக்கிட்டு வந்தது. தற்போது இது தேசிய மாதிரி ஆய்வு அலுவலகத்துடன் இணைக்கப்பட்டு 'தேசியப் புள்ளியியல் அலுவலகம்' (NSO) எனச் செயல்படுகிறது.","difficulty":"medium","topic":"தேசிய வருமானம்"},{"id":820,"subject":"gk","testNumber":9,"question":"தேசிய வருமானத்தைக் கணக்கிடுவதற்குப் பயன்படுத்தப்படும் மூன்று முக்கிய முறைகள் யாவை?","options":["தேவை முறை, அளிப்பு முறை, விலை முறை","உற்பத்தி முறை, வருமான முறை, செலவு முறை","வரி முறை, சேமிப்பு முறை, முதலீட்டு முறை","வேளாண்மை முறை, தொழில் முறை, சேவை முறை"],"correctAnswer":1,"explanation":"தேசிய வருமானம் உற்பத்தி முறை (பண்டம் மற்றும் பணிகளின் மதிப்பு), வருமான முறை (உற்பத்திக் காரணிகளின் வருமானம்) மற்றும் செலவு முறை (இறுதி நுகர்வு மற்றும் முதலீட்டுச் செலவு) ஆகிய மூன்று முறைகளில் கணக்கிடப்படுகிறது. இம்மூன்று முறைகளிலும் கிடைக்கும் தேசிய வருமானம் சமமாக இருக்கும்.","difficulty":"medium","topic":"தேசிய வருமானம்"},{"id":821,"subject":"gk","testNumber":9,"question":"1990ஆம் ஆண்டு 'மனித மேம்பாட்டுக் குறியீட்டை' (HDI) உருவாக்கிய பொருளியல் அறிஞர்கள் யார்?","options":["ஆடம் ஸ்மித் மற்றும் ஆல்பிரட் மார்ஷல்","ஜே.எம். கீன்ஸ் மற்றும் ராக்னர் ஃபிரிஷ்","மஹ்பூப் உல் ஹக் மற்றும் அமர்த்தியா சென்","ஜெகதீஷ் பகவதி மற்றும் அபிஜித் பானர்ஜி"],"correctAnswer":2,"explanation":"பாகிஸ்தான் பொருளியல் அறிஞர் மஹ்பூப் உல் ஹக் மற்றும் இந்திய நோபல் பரிசு பெற்ற பொருளியல் அறிஞர் அமர்த்தியா சென் ஆகியோர் இணைந்து 1990ஆம் ஆண்டு மனித மேம்பாட்டுக் குறியீட்டை (HDI) உருவாக்கினர். இதனை ஐக்கிய நாடுகள் வளர்ச்சித் திட்டம் (UNDP) ஆண்டுதோறும் வெளியிடுகிறது.","difficulty":"medium","topic":"மனித மேம்பாட்டுக் குறியீடு"},{"id":822,"subject":"gk","testNumber":9,"question":"மனித மேம்பாட்டுக் குறியீடு (HDI) கணக்கிடுவதில் பயன்படுத்தப்படும் மூன்று அடிப்படைக் காரணிகள் யாவை?","options":["குழந்தை இறப்பு விகிதம், வேளாண் உற்பத்தி, மின் நுகர்வு","வேலைவாய்ப்பு, தொழில் வளர்ச்சி, ஏற்றுமதி","மக்கள் தொகை, நிலப்பரப்பு, வரி வருவாய்","எதிர்பார்க்கப்படும் ஆயுட்காலம், கல்வி, வாழ்க்கைத் தரம் (தலா வருமானம்)"],"correctAnswer":3,"explanation":"மனித மேம்பாட்டுக் குறியீடு (HDI) என்பது பிறப்பின்போது எதிர்பார்க்கப்படும் சராசரி ஆயுட்காலம் (உடல்நலம்), கல்வி அறிவு மற்றும் பள்ளிக் கல்வி ஆண்டுகள் (கல்வி), மற்றும் தலா மொத்த தேசிய வருமானம் (வாழ்க்கைத் தரம்) ஆகிய மூன்று காரணிகளை அடிப்படையாகக் கொண்டு 0 முதல் 1 என்ற அளவீட்டில் கணக்கிடப்படுகிறது.","difficulty":"medium","topic":"மனித மேம்பாட்டுக் குறியீடு"},{"id":823,"subject":"gk","testNumber":9,"question":"1934ஆம் ஆண்டு 'இந்தியாவிற்கான திட்டமிட்ட பொருளாதாரம்' (Planned Economy for India) என்ற நூலை எழுதி இந்தியாவில் திட்டமிடலுக்கு அடித்தளமிட்டவர் யார்?","options":["ஜெயபிரகாஷ் நாராயணன்","சர் எம். விஸ்வேஸ்வரய்யா","எம்.என். ராய்","ஜவஹர்லால் நேரு"],"correctAnswer":1,"explanation":"புகழ்பெற்ற பொறியாளரும் நிர்வாகியுமான சர் எம். விஸ்வேஸ்வரய்யா 1934ஆம் ஆண்டு 'இந்தியாவிற்கான திட்டமிட்ட பொருளாதாரம்' என்ற நூலை வெளியிட்டார். இதில் இந்தியாவிற்கான பத்தாண்டுத் திட்டத்தை முன்வைத்ததால் இவர் இந்தியப் பொருளாதாரத் திட்டமிடலின் முன்னோடியாகக் கருதப்படுகிறார்.","difficulty":"medium","topic":"இந்தியத் திட்டமிடல்"},{"id":824,"subject":"gk","testNumber":9,"question":"இந்தியத் திட்டக் குழு (Planning Commission) எந்த நாள் மற்றும் ஆண்டில் அமைக்கப்பட்டது?","options":["ஏப்ரல் 1, 1951","ஆகஸ்ட் 15, 1947","ஜனவரி 26, 1950","மார்ச் 15, 1950"],"correctAnswer":3,"explanation":"இந்திய அரசின் அமைச்சரவைத் தீர்மானத்தின் மூலம் மார்ச் 15, 1950 அன்று இந்தியத் திட்டக் குழு அமைக்கப்பட்டது. இது அரசியலமைப்பு சாராத ஆலோசனை அமைப்பாகச் செயல்பட்டு, இந்தியாவின் ஐந்தாண்டுத் திட்டங்களைத் தயாரித்தது.","difficulty":"easy","topic":"இந்தியத் திட்டமிடல்"},{"id":825,"subject":"gk","testNumber":9,"question":"இந்தியத் திட்டக் குழுவின் முதல் தலைவராகப் பணியாற்றியவர் யார்?","options":["சர்தார் வல்லபாய் படேல்","டாக்டர் ராஜேந்திர பிரசாத்","குல்சாரிலால் நந்தா","ஜவஹர்லால் நேரு"],"correctAnswer":3,"explanation":"இந்தியப் பிரதமரே திட்டக் குழுவின் பதவிவழித் தலைவராகச் செயல்பட்டதால், முதல் பிரதமரான ஜவஹர்லால் நேரு திட்டக் குழுவின் முதல் தலைவராக இருந்தார். குல்சாரிலால் நந்தா இதன் முதல் துணைத் தலைவராகப் பணியாற்றினார்.","difficulty":"easy","topic":"இந்தியத் திட்டமிடல்"},{"id":826,"subject":"gk","testNumber":9,"question":"இந்தியாவின் முதல் ஐந்தாண்டுத் திட்டம் (1951–1956) எந்தப் பொருளாதார மாதிரியை அடிப்படையாகக் கொண்டு உருவாக்கப்பட்டது?","options":["கீன்சியன் மாதிரி","ஹாரட்-டோமர் மாதிரி","காட்கில் மாதிரி","மஹலனோபிஸ் மாதிரி"],"correctAnswer":1,"explanation":"இந்தியாவின் முதல் ஐந்தாண்டுத் திட்டம் (1951–1956) 'ஹாரட்-டோமர் மாதிரியை' (Harrod-Domar Model) அடிப்படையாகக் கொண்டது. இத்திட்டம் வேளாண்மை, நீர்ப்பாசனம் மற்றும் மின்சக்தி மேம்பாட்டிற்கு முதன்மை முக்கியத்துவம் அளித்தது.","difficulty":"medium","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":827,"subject":"gk","testNumber":9,"question":"கனரகத் தொழில்களின் வளர்ச்சிக்கு முன்னுரிமை அளித்த இந்தியாவின் இரண்டாவது ஐந்தாண்டுத் திட்டம் (1956–1961) யாருடைய மாதிரியை அடிப்படையாகக் கொண்டது?","options":["ஜான் சாண்டி மாதிரி","அசோக் ருத்ரா மாதிரி","பி.சி. மஹலனோபிஸ் மாதிரி","ஹாரட்-டோமர் மாதிரி"],"correctAnswer":2,"explanation":"புள்ளியியல் அறிஞர் பி.சி. மஹலனோபிஸ் உருவாக்கிய மாதிரியின் அடிப்படையில் இரண்டாவது ஐந்தாண்டுத் திட்டம் (1956–1961) செயல்படுத்தப்பட்டது. இத்திட்டக் காலத்தில் பிலாய், துர்காபூர் மற்றும் ரூர்கேலா ஆகிய இடங்களில் இரும்பு எஃகு ஆலைகள் நிறுவப்பட்டன.","difficulty":"easy","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":828,"subject":"gk","testNumber":9,"question":"இந்தியாவின் மூன்றாவது ஐந்தாண்டுத் திட்டம் (1961–1966) எவ்வாறு அழைக்கப்படுகிறது?","options":["மக்கள் திட்டம்","காட்கில் திட்டம்","காந்தியத் திட்டம்","பாம்பே திட்டம்"],"correctAnswer":1,"explanation":"மூன்றாவது ஐந்தாண்டுத் திட்டம் (1961–1966) 'காட்கில் திட்டம்' (Gadgil Yojana) என அழைக்கப்படுகிறது. சுதந்திரமான மற்றும் சுயமாக வளரும் பொருளாதாரத்தை உருவாக்குவதே இதன் நோக்கமாக இருந்தது; ஆனால் சீன-இந்தியப் போர், பாகிஸ்தான் போர் மற்றும் கடும் வறட்சியால் இத்திட்டம் இலக்கை அடையவில்லை.","difficulty":"hard","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":829,"subject":"gk","testNumber":9,"question":"இந்தியத் திட்டமிடல் வரலாற்றில் 'திட்ட விடுமுறைக் காலம்' (Plan Holiday) என அழைக்கப்படும் காலகட்டம் எது?","options":["1966–1969","1990–1992","1961–1964","1978–1980"],"correctAnswer":0,"explanation":"மூன்றாவது ஐந்தாண்டுத் திட்டத்தின் தோல்வி, போர்கள் மற்றும் நிதி நெருக்கடி காரணமாக நான்காவது ஐந்தாண்டுத் திட்டம் உடனடியாகத் தொடங்கப்படாமல் 1966 முதல் 1969 வரை மூன்று ஓராண்டுத் திட்டங்கள் செயல்படுத்தப்பட்டன. இக்காலகட்டம் 'திட்ட விடுமுறைக் காலம்' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":830,"subject":"gk","testNumber":9,"question":"'வறுமை ஒழிப்பு' (கரீபி ஹடாவோ) மற்றும் சுயசார்பு அடைதல் ஆகியவற்றை முதன்மை நோக்கமாகக் கொண்ட ஐந்தாண்டுத் திட்டம் எது?","options":["ஆறாவது ஐந்தாண்டுத் திட்டம்","நான்காவது ஐந்தாண்டுத் திட்டம்","ஏழாவது ஐந்தாண்டுத் திட்டம்","ஐந்தாவது ஐந்தாண்டுத் திட்டம்"],"correctAnswer":3,"explanation":"ஐந்தாவது ஐந்தாண்டுத் திட்டம் (1974–1979) டி.பி. தார் வரைவு மாதிரியில் உருவாக்கப்பட்டு, 'வறுமை ஒழிப்பு' (கரீபி ஹடாவோ) மற்றும் சுயசார்பு ஆகியவற்றை முதன்மை நோக்கங்களாகக் கொண்டது. இத்திட்டம் ஒரு ஆண்டு முன்னதாகவே 1978இல் முடிவுக்குக் கொண்டுவரப்பட்டது.","difficulty":"medium","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":831,"subject":"gk","testNumber":9,"question":"இந்தியாவில் 'சுழல் திட்டம்' (Rolling Plan) எந்தக் காலகட்டத்தில் அறிமுகப்படுத்தப்பட்டது?","options":["1974–1977","1966–1969","1978–1980","1990–1992"],"correctAnswer":2,"explanation":"1978ஆம் ஆண்டு ஆட்சிக்கு வந்த ஜனதா அரசு, ஐந்தாவது ஐந்தாண்டுத் திட்டத்தை நிறுத்திவிட்டு 1978–1980 காலகட்டத்தில் 'சுழல் திட்டத்தை' (Rolling Plan) அறிமுகப்படுத்தியது. இத்திட்டக் கருத்தை முன்மொழிந்தவர் குன்னார் மிர்டால் ஆவார்.","difficulty":"hard","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":832,"subject":"gk","testNumber":9,"question":"இந்தியாவில் திட்டக் குழு தயாரித்த ஐந்தாண்டுத் திட்டங்களுக்கு இறுதி ஒப்புதல் வழங்கிய அமைப்பு எது?","options":["தேசிய வளர்ச்சிக் குழு (NDC)","இந்திய ரிசர்வ் வங்கி","நிதி ஆணையம்","மத்திய அமைச்சரவை"],"correctAnswer":0,"explanation":"ஆகஸ்ட் 6, 1952 அன்று அமைக்கப்பட்ட தேசிய வளர்ச்சிக் குழு (National Development Council) ஐந்தாண்டுத் திட்டங்களுக்கு இறுதி ஒப்புதல் அளிக்கும் உயரிய அமைப்பாகச் செயல்பட்டது. பிரதமர் இதன் தலைவராகவும், அனைத்து மாநில முதலமைச்சர்கள் இதன் உறுப்பினர்களாகவும் இருந்தனர்.","difficulty":"medium","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":833,"subject":"gk","testNumber":9,"question":"இந்தியாவின் பன்னிரண்டாவது ஐந்தாண்டுத் திட்டத்தின் (2012–2017) மைய நோக்கம் என்ன?","options":["வறுமை ஒழிப்பு மற்றும் வேலைவாய்ப்பு","உணவு, வேலை மற்றும் உற்பத்தித்திறன்","விரைவான, அதிக உள்ளடக்கிய மற்றும் நிலையான வளர்ச்சி","மனித வள மேம்பாடு"],"correctAnswer":2,"explanation":"இந்தியாவின் இறுதி ஐந்தாண்டுத் திட்டமான 12வது ஐந்தாண்டுத் திட்டத்தின் (2012–2017) மைய நோக்கம் 'விரைவான, அதிக உள்ளடக்கிய மற்றும் நிலையான வளர்ச்சி' (Faster, More Inclusive and Sustainable Growth) என்பதாகும். இதில் 8% பொருளாதார வளர்ச்சி இலக்காக நிர்ணயிக்கப்பட்டது.","difficulty":"medium","topic":"ஐந்தாண்டுத் திட்டங்கள்"},{"id":834,"subject":"gk","testNumber":9,"question":"திட்டக் குழுவிற்கு மாற்றாக 'நிதி ஆயோக்' (NITI Aayog) எப்போது அமைக்கப்பட்டது?","options":["ஜனவரி 1, 2015","ஏப்ரல் 1, 2015","ஜனவரி 26, 2016","ஆகஸ்ட் 15, 2014"],"correctAnswer":0,"explanation":"65 ஆண்டுகள் செயல்பட்டு வந்த திட்டக் குழுவிற்கு மாற்றாக ஜனவரி 1, 2015 அன்று 'நிதி ஆயோக்' (NITI Aayog) அமைக்கப்பட்டது. இது இந்திய அரசின் கொள்கை உருவாக்கும் அறிவுசார் அமைப்பாகவும் (Think Tank), கூட்டுறவுக் கூட்டாட்சியை மேம்படுத்தும் அமைப்பாகவும் செயல்படுகிறது.","difficulty":"easy","topic":"நிதி ஆயோக்"},{"id":835,"subject":"gk","testNumber":9,"question":"NITI Aayog என்பதன் சரியான விரிவாக்கம் எது?","options":["National Initiative for Trade in India","National Institution for Transforming India","National Integration for Transforming India","National Institute for Technical India"],"correctAnswer":1,"explanation":"NITI Aayog என்பதன் விரிவாக்கம் 'National Institution for Transforming India' (இந்தியாவை மாற்றுவதற்கான தேசிய நிறுவனம்) என்பதாகும். இதன் முதல் துணைத் தலைவராக அரவிந்த் பனகாரியா நியமிக்கப்பட்டார்.","difficulty":"easy","topic":"நிதி ஆயோக்"},{"id":836,"subject":"gk","testNumber":9,"question":"நிதி ஆயோக்கின் (NITI Aayog) பதவிவழித் தலைவர் யார்?","options":["இந்திய ரிசர்வ் வங்கி ஆளுநர்","இந்தியப் பிரதமர்","மத்திய நிதி அமைச்சர்","இந்தியக் குடியரசுத் தலைவர்"],"correctAnswer":1,"explanation":"இந்தியப் பிரதமரே நிதி ஆயோக்கின் பதவிவழித் தலைவராகச் செயல்படுகிறார். இதன் நிர்வாகக் குழுவில் அனைத்து மாநிலங்களின் முதலமைச்சர்கள் மற்றும் யூனியன் பிரதேசங்களின் துணைநிலை ஆளுநர்கள் இடம்பெற்றுள்ளனர்.","difficulty":"easy","topic":"நிதி ஆயோக்"},{"id":837,"subject":"gk","testNumber":9,"question":"1991ஆம் ஆண்டு இந்தியாவில் புதிய பொருளாதாரக் கொள்கை (LPG) அறிவிக்கப்பட்டபோது மத்திய நிதி அமைச்சராகப் பணியாற்றியவர் யார்?","options":["யஷ்வந்த் சின்ஹா","ப. சிதம்பரம்","டாக்டர் மன்மோகன் சிங்","பிரணாப் முகர்ஜி"],"correctAnswer":2,"explanation":"1991ஆம் ஆண்டு பிரதமர் பி.வி. நரசிம்ம ராவ் தலைமையிலான அரசில் நிதி அமைச்சராக இருந்த டாக்டர் மன்மோகன் சிங் புதிய பொருளாதாரக் கொள்கையை அறிமுகப்படுத்தினார். அந்நியச் செலாவணி நெருக்கடியிலிருந்து இந்தியப் பொருளாதாரத்தை மீட்க இக்கொள்கை பெரிதும் உதவியது.","difficulty":"easy","topic":"புதிய பொருளாதாரக் கொள்கை 1991"},{"id":838,"subject":"gk","testNumber":9,"question":"1991ஆம் ஆண்டு புதிய பொருளாதாரக் கொள்கையின் (LPG) மூன்று முக்கியத் தூண்கள் யாவை?","options":["ஏற்றுமதி, இறக்குமதி, பணமதிப்பிழப்பு","வேளாண்மை, தொழில்மயம், நகரமயம்","நாட்டுடைமை, திட்டமிடல், பாதுகாப்பு","தாராளமயமாக்கல், தனியார்மயமாக்கல், உலகமயமாக்கல்"],"correctAnswer":3,"explanation":"1991ஆம் ஆண்டு புதிய பொருளாதாரக் கொள்கையின் மூன்று முக்கிய அம்சங்கள் தாராளமயமாக்கல் (Liberalisation), தனியார்மயமாக்கல் (Privatisation) மற்றும் உலகமயமாக்கல் (Globalisation) ஆகும். சுருக்கமாக இது LPG கொள்கை என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"புதிய பொருளாதாரக் கொள்கை 1991"},{"id":839,"subject":"gk","testNumber":9,"question":"தொழில் தொடங்குவதற்கான அரசின் உரிம முறை (Licensing) மற்றும் தேவையற்ற கட்டுப்பாடுகளைத் தளர்த்தும் கொள்கை எவ்வாறு அழைக்கப்படுகிறது?","options":["நாட்டுடைமையாக்கல்","உலகமயமாக்கல்","தாராளமயமாக்கல்","வணிகமயமாக்கல்"],"correctAnswer":2,"explanation":"தொழில் மற்றும் வணிக நடவடிக்கைகளில் அரசின் நேரடிக் கட்டுப்பாடுகள், உரிம முறை மற்றும் ஒதுக்கீட்டு வரம்புகளை நீக்கி அல்லது தளர்த்திச் சந்தை சக்திகளுக்கு வாய்ப்பு அளிக்கும் நடைமுறை 'தாராளமயமாக்கல்' (Liberalisation) எனப்படுகிறது.","difficulty":"medium","topic":"புதிய பொருளாதாரக் கொள்கை 1991"},{"id":840,"subject":"gk","testNumber":9,"question":"அரசு பொதுத்துறை நிறுவனங்களின் பங்குகளைத் தனியார் துறைக்கு விற்பனை செய்து நிதி திரட்டும் நடைமுறை எவ்வாறு அழைக்கப்படுகிறது?","options":["பணமதிப்பிழப்பு","வரி விலக்கு","முதலீட்டு விலக்கல் (Disinvestment)","பணவீக்கம்"],"correctAnswer":2,"explanation":"பொதுத்துறை நிறுவனங்களின் பங்குகளைப் பகுதியாகவோ அல்லது முழுமையாகவோ தனியார் துறைக்கு விற்பனை செய்யும் நடைமுறை 'முதலீட்டு விலக்கல்' (Disinvestment) எனப்படும். இது தனியார்மயமாக்கலின் முக்கியக் கருவியாகும்.","difficulty":"hard","topic":"புதிய பொருளாதாரக் கொள்கை 1991"},{"id":841,"subject":"gk","testNumber":9,"question":"இந்தியாவின் மைய வங்கியான 'இந்திய ரிசர்வ் வங்கி' (RBI) எப்போது தொடங்கப்பட்டது?","options":["ஜூலை 19, 1969","ஜூலை 1, 1955","ஜனவரி 1, 1949","ஏப்ரல் 1, 1935"],"correctAnswer":3,"explanation":"ஹில்டன் யங் ஆணையத்தின் பரிந்துரையின் அடிப்படையில் இயற்றப்பட்ட இந்திய ரிசர்வ் வங்கிச் சட்டம் 1934 இன் கீழ், ஏப்ரல் 1, 1935 அன்று இந்திய ரிசர்வ் வங்கி கொல்கத்தாவில் தொடங்கப்பட்டது. 1937ஆம் ஆண்டு இதன் தலைமையகம் மும்பைக்கு மாற்றப்பட்டது.","difficulty":"easy","topic":"வங்கியியல்"},{"id":842,"subject":"gk","testNumber":9,"question":"இந்திய ரிசர்வ் வங்கி (RBI) எந்த நாள் மற்றும் ஆண்டில் நாட்டுடைமையாக்கப்பட்டது?","options":["ஜனவரி 1, 1949","ஆகஸ்ட் 15, 1947","ஜனவரி 26, 1950","ஜூலை 19, 1969"],"correctAnswer":0,"explanation":"தொடக்கத்தில் தனியார் பங்குதாரர்கள் வங்கியாகத் தொடங்கப்பட்ட இந்திய ரிசர்வ் வங்கி, சுதந்திரத்திற்குப் பின் ஜனவரி 1, 1949 அன்று நாட்டுடைமையாக்கப்பட்டு முழுமையாக இந்திய அரசின் கட்டுப்பாட்டின் கீழ் கொண்டுவரப்பட்டது.","difficulty":"easy","topic":"வங்கியியல்"},{"id":843,"subject":"gk","testNumber":9,"question":"இந்தியாவில் ஒரு ரூபாய் காகிதப் பணம் மற்றும் அனைத்து நாணயங்களையும் வெளியிடும் அதிகாரம் யாருக்கு உள்ளது?","options":["பாரத ஸ்டேட் வங்கி","இந்திய ரிசர்வ் வங்கி","நிதி ஆணையம்","இந்திய அரசின் நிதி அமைச்சகம்"],"correctAnswer":3,"explanation":"இந்தியாவில் இரண்டு ரூபாய் மற்றும் அதற்கு மேற்பட்ட மதிப்புள்ள காகிதப் பணத்தை இந்திய ரிசர்வ் வங்கி வெளியிடுகிறது. ஆனால் ஒரு ரூபாய் காகிதப் பணம் மற்றும் அனைத்து நாணயங்களையும் இந்திய அரசின் நிதி அமைச்சகம் வெளியிடுகிறது; ஒரு ரூபாய் நோட்டில் நிதிச் செயலாளர் கையொப்பமிடுவார்.","difficulty":"medium","topic":"வங்கியியல்"},{"id":844,"subject":"gk","testNumber":9,"question":"இந்திய ரிசர்வ் வங்கி, வணிக வங்கிகளுக்குக் குறுகிய காலக் கடன்களை வழங்கும்போது வசூலிக்கும் வட்டி விகிதம் எவ்வாறு அழைக்கப்படுகிறது?","options":["ரொக்க இருப்பு விகிதம்","ரிவர்ஸ் ரெப்போ விகிதம்","ரெப்போ விகிதம் (Repo Rate)","சட்டப்பூர்வ நீர்மை விகிதம்"],"correctAnswer":2,"explanation":"வணிக வங்கிகள் தங்களின் குறுகிய கால நிதித் தேவைக்காக அரசுப் பத்திரங்களை அடமானம் வைத்து இந்திய ரிசர்வ் வங்கியிடம் பெறும் கடனுக்குச் செலுத்தும் வட்டி விகிதம் 'ரெப்போ விகிதம்' (Repo Rate) எனப்படும். பணவீக்கத்தைக் கட்டுப்படுத்த RBI ரெப்போ விகிதத்தை உயர்த்தும்.","difficulty":"medium","topic":"பணவியல் கொள்கை"},{"id":845,"subject":"gk","testNumber":9,"question":"வணிக வங்கிகள் தங்களிடம் உள்ள உபரி நிதியை இந்திய ரிசர்வ் வங்கியில் குறுகிய காலத்திற்கு வைப்பு வைக்கும்போது RBI வழங்கும் வட்டி விகிதம் எது?","options":["வங்கி விகிதம் (Bank Rate)","அடிப்படை வட்டி விகிதம் (Base Rate)","ரெப்போ விகிதம் (Repo Rate)","ரிவர்ஸ் ரெப்போ விகிதம் (Reverse Repo Rate)"],"correctAnswer":3,"explanation":"வணிக வங்கிகள் தங்களிடம் உள்ள உபரிப் பணத்தை இந்திய ரிசர்வ் வங்கியில் வைப்பு வைக்கும்போது, அதற்கு RBI வழங்கும் வட்டி விகிதம் 'ரிவர்ஸ் ரெப்போ விகிதம்' (Reverse Repo Rate) எனப்படும். சந்தையில் பணப் புழக்கத்தைக் குறைக்க RBI இவ்விகிதத்தை உயர்த்தும்.","difficulty":"medium","topic":"பணவியல் கொள்கை"},{"id":846,"subject":"gk","testNumber":9,"question":"வணிக வங்கிகள் தங்களின் மொத்த வைப்புத்தொகையில் ஒரு குறிப்பிட்ட சதவீதத்தை இந்திய ரிசர்வ் வங்கியில் ரொக்கமாகக் கட்டாயம் வைத்திருக்க வேண்டிய விகிதம் எது?","options":["ரொக்க இருப்பு விகிதம் (CRR)","சட்டப்பூர்வ நீர்மை விகிதம் (SLR)","வங்கி விகிதம்","ரெப்போ விகிதம்"],"correctAnswer":0,"explanation":"வணிக வங்கிகள் தங்களின் மொத்தக் கால மற்றும் கேட்பு வைப்புத்தொகையில் (NDTL) ஒரு குறிப்பிட்ட சதவீதத்தை இந்திய ரிசர்வ் வங்கியில் ரொக்க இருப்பாக வைத்திருக்க வேண்டும்; இது 'ரொக்க இருப்பு விகிதம்' (Cash Reserve Ratio - CRR) எனப்படும். இதற்கு RBI வட்டி எதுவும் வழங்குவதில்லை.","difficulty":"medium","topic":"பணவியல் கொள்கை"},{"id":847,"subject":"gk","testNumber":9,"question":"வணிக வங்கிகள் தங்களின் மொத்த வைப்புத்தொகையில் ஒரு குறிப்பிட்ட சதவீதத்தைத் தங்களிடமே ரொக்கம், தங்கம் அல்லது அங்கீகரிக்கப்பட்ட அரசுப் பத்திரங்களாக வைத்திருக்க வேண்டிய விகிதம் எது?","options":["விளிம்பு நிலை வசதி விகிதம் (MSF)","சட்டப்பூர்வ நீர்மை விகிதம் (SLR)","ரொக்க இருப்பு விகிதம் (CRR)","ரெப்போ விகிதம்"],"correctAnswer":1,"explanation":"வணிக வங்கிகள் கடன் வழங்குவதற்கு முன்பு, தங்களின் மொத்த வைப்புத்தொகையில் குறிப்பிட்ட சதவீதத்தைத் தங்களிடமே ரொக்கம், தங்கம் அல்லது அரசுப் பத்திரங்கள் வடிவில் நீர்மைச் சொத்துகளாக வைத்திருக்க வேண்டிய கட்டாய விகிதம் 'சட்டப்பூர்வ நீர்மை விகிதம்' (Statutory Liquidity Ratio - SLR) எனப்படும்.","difficulty":"hard","topic":"பணவியல் கொள்கை"},{"id":848,"subject":"gk","testNumber":9,"question":"இந்தியாவில் முதன்முறையாக 14 பெரிய வணிக வங்கிகள் எப்போது நாட்டுடைமையாக்கப்பட்டன?","options":["ஏப்ரல் 15, 1980","ஜூலை 1, 1955","ஜனவரி 1, 1949","ஜூலை 19, 1969"],"correctAnswer":3,"explanation":"பிரதமர் இந்திரா காந்தி ஆட்சிக் காலத்தில், ₹50 கோடிக்கும் மேல் வைப்புத்தொகை கொண்ட 14 பெரிய வணிக வங்கிகள் ஜூலை 19, 1969 அன்று நாட்டுடைமையாக்கப்பட்டன. கிராமப்புறங்களுக்கும் வேளாண்மைக்கும் வங்கிக் கடன்கள் எளிதில் கிடைக்க இம்முடிவு எடுக்கப்பட்டது.","difficulty":"easy","topic":"வங்கியியல்"},{"id":849,"subject":"gk","testNumber":9,"question":"இந்தியாவில் இரண்டாவது கட்டமாக மேலும் 6 வணிக வங்கிகள் எந்த ஆண்டு நாட்டுடைமையாக்கப்பட்டன?","options":["1980","1991","1982","1975"],"correctAnswer":0,"explanation":"1969இல் 14 வங்கிகள் நாட்டுடைமையாக்கப்பட்டதைத் தொடர்ந்து, ₹200 கோடிக்கும் மேல் வைப்புத்தொகை கொண்ட மேலும் 6 வணிக வங்கிகள் ஏப்ரல் 15, 1980 அன்று நாட்டுடைமையாக்கப்பட்டன.","difficulty":"medium","topic":"வங்கியியல்"},{"id":850,"subject":"gk","testNumber":9,"question":"1955ஆம் ஆண்டு நாட்டுடைமையாக்கப்பட்டு 'பாரத ஸ்டேட் வங்கி' (SBI) எனப் பெயர் மாற்றப்பட்ட வங்கி எது?","options":["பஞ்சாப் நேஷனல் பேங்க்","இம்பீரியல் பேங்க் ஆஃப் இந்தியா","பேங்க் ஆஃப் ஹிந்துஸ்தான்","மெட்ராஸ் பேங்க்"],"correctAnswer":1,"explanation":"1921ஆம் ஆண்டு வங்காளம், மும்பை மற்றும் சென்னை மாகாண வங்கிகளை இணைத்து உருவாக்கப்பட்ட 'இம்பீரியல் பேங்க் ஆஃப் இந்தியா', கோர்வாலா குழுவின் பரிந்துரையின்படி ஜூலை 1, 1955 அன்று நாட்டுடைமையாக்கப்பட்டு 'பாரத ஸ்டேட் வங்கி' (SBI) எனப் பெயர் மாற்றப்பட்டது.","difficulty":"easy","topic":"வங்கியியல்"},{"id":851,"subject":"gk","testNumber":9,"question":"தேசிய வேளாண்மை மற்றும் ஊரக மேம்பாட்டு வங்கி (NABARD) எந்த ஆண்டு நிறுவப்பட்டது?","options":["1975","1980","1982","1990"],"correctAnswer":2,"explanation":"பி. சிவராமன் குழுவின் பரிந்துரையின் அடிப்படையில் ஜூலை 12, 1982 அன்று தேசிய வேளாண்மை மற்றும் ஊரக மேம்பாட்டு வங்கி (NABARD) நிறுவப்பட்டது. இதன் தலைமையகம் மும்பையில் உள்ளது; இது வேளாண்மை மற்றும் கிராமப்புற வளர்ச்சிக்கான உச்சகட்ட மறுநிதி வங்கியாகச் செயல்படுகிறது.","difficulty":"easy","topic":"வங்கியியல்"},{"id":852,"subject":"gk","testNumber":9,"question":"இந்திய சிறுதொழில் மேம்பாட்டு வங்கி (SIDBI) எந்த ஆண்டு நிறுவப்பட்டது மற்றும் அதன் தலைமையகம் எங்கு உள்ளது?","options":["1990; லக்னோ","1982; மும்பை","1992; சென்னை","1988; புது தில்லி"],"correctAnswer":0,"explanation":"குறு, சிறு மற்றும் நடுத்தரத் தொழில்களின் மேம்பாடு மற்றும் நிதி உதவிக்காக ஏப்ரல் 2, 1990 அன்று இந்திய சிறுதொழில் மேம்பாட்டு வங்கி (SIDBI) நிறுவப்பட்டது. இதன் தலைமையகம் உத்தரப் பிரதேச மாநிலத்தின் லக்னோவில் அமைந்துள்ளது.","difficulty":"hard","topic":"வங்கியியல்"},{"id":853,"subject":"gk","testNumber":9,"question":"இந்தியப் பங்குச் சந்தையை ஒழுங்குபடுத்தும் 'இந்தியப் பங்கு மற்றும் பரிவர்த்தனை வாரியம்' (SEBI) எந்த ஆண்டு சட்டப்பூர்வ அதிகாரத்தைப் பெற்றது?","options":["1990","1992","1995","1988"],"correctAnswer":1,"explanation":"இந்தியப் பங்கு மற்றும் பரிவர்த்தனை வாரியம் (SEBI) 1988ஆம் ஆண்டு அமைக்கப்பட்டு, SEBI சட்டம் 1992 மூலம் ஜனவரி 30, 1992 அன்று சட்டப்பூர்வ அதிகாரத்தைப் பெற்றது. முதலீட்டாளர்களின் நலனைப் பாதுகாப்பதும் பங்குச் சந்தையை ஒழுங்குபடுத்துவதும் இதன் முதன்மைப் பணிகளாகும்.","difficulty":"hard","topic":"வங்கியியல்"},{"id":854,"subject":"gk","testNumber":9,"question":"'குறைந்த அளவு பண்டங்களை அதிக அளவு பணம் துரத்தும் நிலை' என்று பணவீக்கத்தை (Inflation) வரையறுத்த பொருளியல் அறிஞர் யார்?","options":["கிரிகோரி","கோல்போர்ன் (Coulborn)","ஜே.எம். கீன்ஸ்","இர்விங் ஃபிஷர்"],"correctAnswer":1,"explanation":"பொருளியல் அறிஞர் கோல்போர்ன் (Coulborn) பணவீக்கத்தைக் 'குறைந்த அளவு பண்டங்களை அதிக அளவு பணம் துரத்தும் நிலை' என்று விளக்கியுள்ளார். பணவீக்கத்தின்போது பொது விலைவாசி தொடர்ச்சியாக உயர்ந்து பணத்தின் வாங்கும் சக்தி குறைகிறது.","difficulty":"hard","topic":"பணவியல் கொள்கை"},{"id":855,"subject":"gk","testNumber":9,"question":"பொருளாதாரத்தில் பொருள்களின் பொது விலை மட்டம் தொடர்ச்சியாகக் குறைந்து பணத்தின் மதிப்பு உயரும் நிலை எவ்வாறு அழைக்கப்படுகிறது?","options":["மீள்பணவீக்கம்","தேக்கவீக்கம்","பணவீக்கம்","பணவாட்டம் (Deflation)"],"correctAnswer":3,"explanation":"பணப் புழக்கம் குறைவதால் பொருள்களின் பொது விலைவாசி தொடர்ச்சியாகக் குறைந்து, உற்பத்தி மற்றும் வேலைவாய்ப்பு வீழ்ச்சியடையும் நிலை 'பணவாட்டம்' (Deflation) எனப்படும். இது பணவீக்கத்திற்கு நேர் எதிரான நிலையாகும்.","difficulty":"easy","topic":"பணவியல் கொள்கை"},{"id":856,"subject":"gk","testNumber":9,"question":"பொருளாதார வளர்ச்சித் தேக்கமும் (வேலைவாய்ப்பின்மையும்) அதிக பணவீக்கமும் ஒரே நேரத்தில் காணப்படும் நிலை எவ்வாறு அழைக்கப்படுகிறது?","options":["தேக்கவீக்கம் (Stagflation)","தவழும் பணவீக்கம்","மீள்பணவீக்கம் (Reflation)","நடக்கும் பணவீக்கம்"],"correctAnswer":0,"explanation":"பொருளாதாரத் தேக்கம் (Stagnation) மற்றும் பணவீக்கம் (Inflation) ஆகிய இரண்டும் இணைந்து, வேலைவாய்ப்பின்மையும் விலைவாசி உயர்வும் ஒரே நேரத்தில் நிலவும் சூழல் 'தேக்கவீக்கம்' (Stagflation) என அழைக்கப்படுகிறது.","difficulty":"hard","topic":"பணவியல் கொள்கை"},{"id":857,"subject":"gk","testNumber":9,"question":"இந்திய அரசியலமைப்பின் எந்தச் சட்டப்பிரிவு மத்திய அரசின் 'ஆண்டு நிதிநிலை அறிக்கை' (Budget) குறித்துக் கூறுகிறது?","options":["சட்டப்பிரிவு 112","சட்டப்பிரிவு 280","சட்டப்பிரிவு 110","சட்டப்பிரிவு 360"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்பில் 'பட்ஜெட்' என்ற சொல் நேரடியாக இடம்பெறவில்லை; அதற்குப் பதிலாகச் சட்டப்பிரிவு 112இன் கீழ் 'ஆண்டு நிதிநிலை அறிக்கை' (Annual Financial Statement) எனக் குறிப்பிடப்பட்டுள்ளது. இது ஒவ்வொரு நிதியாண்டின் (ஏப்ரல் 1 முதல் மார்ச் 31) வரவு-செலவு மதிப்பீட்டைக் காட்டுகிறது.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":858,"subject":"gk","testNumber":9,"question":"அரசின் மொத்தச் செலவானது, கடன் அல்லாத மொத்த வருவாயை விட அதிகமாக இருக்கும்போது ஏற்படும் பற்றாக்குறை எவ்வாறு அழைக்கப்படுகிறது?","options":["வருவாய்ப் பற்றாக்குறை","முதன்மைப் பற்றாக்குறை","வணிகப் பற்றாக்குறை","நிதிப் பற்றாக்குறை (Fiscal Deficit)"],"correctAnswer":3,"explanation":"நிதிப் பற்றாக்குறை = அரசின் மொத்தச் செலவு – (வருவாய் வரவுகள் + கடன் அல்லாத மூலதன வரவுகள்). இது ஓர் ஆண்டில் அரசு வாங்க வேண்டிய மொத்தக் கடன் தேவையைத் துல்லியமாகக் காட்டுகிறது.","difficulty":"hard","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":859,"subject":"gk","testNumber":9,"question":"கீழ்க்கண்டவற்றுள் எது நேர்முக வரி (Direct Tax) அல்ல?","options":["நிறுவன வரி","சரக்கு மற்றும் சேவை வரி (GST)","வருமான வரி","சொத்து வரி"],"correctAnswer":1,"explanation":"வருமான வரி, நிறுவன வரி மற்றும் சொத்து வரி ஆகியவை வரி விதிக்கப்படுபவராலேயே நேரடியாகச் செலுத்தப்படும் நேர்முக வரிகள் ஆகும். ஆனால் சரக்கு மற்றும் சேவை வரி (GST) வரிச்சுமையை நுகர்வோருக்கு மாற்றக்கூடிய மறைமுக வரியாகும்.","difficulty":"easy","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":860,"subject":"gk","testNumber":9,"question":"சமத்துவ விதி, நிச்சய விதி, வசதி விதி மற்றும் சிக்கன விதி ஆகிய நான்கு 'வரி விதிப்பு விதிகளை' (Canons of Taxation) வகுத்தவர் யார்?","options":["டேவிட் ரிக்கார்டோ","டால்டன்","ஆல்பிரட் மார்ஷல்","ஆடம் ஸ்மித்"],"correctAnswer":3,"explanation":"ஆடம் ஸ்மித் தனது 'நாடுகளின் செல்வம்' என்ற நூலில் ஒரு சிறந்த வரி அமைப்பிற்குத் தேவையான சமத்துவ விதி, நிச்சய விதி, வசதி விதி மற்றும் சிக்கன விதி ஆகிய நான்கு வரி விதிப்பு விதிகளைக் கூறியுள்ளார்.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":861,"subject":"gk","testNumber":9,"question":"தனிநபரின் வருமானம் அதிகரிக்கும்போது வரி விகிதமும் அதிகரிக்கும் வரி விதிப்பு முறை எவ்வாறு அழைக்கப்படுகிறது?","options":["விகிதாச்சார வரி","தேய்வுவீத வரி","வளர்வீத வரி (Progressive Tax)","மறைமுக வரி"],"correctAnswer":2,"explanation":"வருமானம் உயரும்போது வரி விகிதமும் உயரும் வரி முறை 'வளர்வீத வரி' (Progressive Tax) எனப்படும். இந்தியாவின் தனிநபர் வருமான வரி இதற்குச் சிறந்த எடுத்துக்காட்டாகும்; இது பொருளாதார ஏற்றத்தாழ்வைக் குறைக்க உதவுகிறது.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":862,"subject":"gk","testNumber":9,"question":"'ஒரே நாடு, ஒரே வரி' என்ற அடிப்படையில் இந்தியாவில் சரக்கு மற்றும் சேவை வரி (GST) எப்போது நடைமுறைக்கு வந்தது?","options":["ஜனவரி 1, 2018","ஏப்ரல் 1, 2017","நவம்பர் 8, 2016","ஜூலை 1, 2017"],"correctAnswer":3,"explanation":"பல மத்திய மற்றும் மாநில மறைமுக வரிகளை ஒருங்கிணைத்து, 'ஒரே நாடு, ஒரே சந்தை, ஒரே வரி' என்ற நோக்கத்துடன் சரக்கு மற்றும் சேவை வரி (GST) ஜூலை 1, 2017 அன்று இந்தியாவில் நடைமுறைக்கு வந்தது.","difficulty":"easy","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":863,"subject":"gk","testNumber":9,"question":"இந்தியாவில் சரக்கு மற்றும் சேவை வரியை (GST) அறிமுகப்படுத்திய அரசியலமைப்புச் சட்டத் திருத்தம் எது?","options":["100வது திருத்தச் சட்டம்","102வது திருத்தச் சட்டம்","99வது திருத்தச் சட்டம்","101வது திருத்தச் சட்டம்"],"correctAnswer":3,"explanation":"2016ஆம் ஆண்டு இயற்றப்பட்ட 101வது அரசியலமைப்புத் திருத்தச் சட்டம் இந்தியாவில் சரக்கு மற்றும் சேவை வரியை (GST) அறிமுகப்படுத்தியது. இத்திருத்தத்தின் மூலம் சட்டப்பிரிவு 279Aஇன் கீழ் GST மன்றம் (GST Council) அமைக்கப்பட்டது.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":864,"subject":"gk","testNumber":9,"question":"மத்திய மற்றும் மாநில அரசுகளுக்கிடையே வரி வருவாயைப் பகிர்ந்தளிக்கப் பரிந்துரைக்கும் 'நிதி ஆணையம்' (Finance Commission) அரசியலமைப்பின் எந்தப் பிரிவின் கீழ் அமைக்கப்படுகிறது?","options":["சட்டப்பிரிவு 266","சட்டப்பிரிவு 300A","சட்டப்பிரிவு 324","சட்டப்பிரிவு 280"],"correctAnswer":3,"explanation":"இந்திய அரசியலமைப்பின் சட்டப்பிரிவு 280இன் கீழ் ஐந்து ஆண்டுகளுக்கு ஒருமுறை குடியரசுத் தலைவரால் நிதி ஆணையம் அமைக்கப்படுகிறது. இது மத்திய-மாநில அரசுகளுக்கிடையேயான நிதிப் பகிர்வு குறித்த பரிந்துரைகளை வழங்கும் அரசியலமைப்பு அமைப்பாகும்.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":865,"subject":"gk","testNumber":9,"question":"1951ஆம் ஆண்டு அமைக்கப்பட்ட இந்தியாவின் முதல் நிதி ஆணையத்தின் தலைவர் யார்?","options":["கே.சி. நியோகி","பி.வி. ராஜமன்னார்","கே. சந்தானம்","ஏ.கே. சந்தா"],"correctAnswer":0,"explanation":"இந்தியாவின் முதல் நிதி ஆணையம் 1951ஆம் ஆண்டு கே.சி. நியோகி தலைமையில் அமைக்கப்பட்டது. இதன் பரிந்துரைகள் 1952 முதல் 1957 வரையிலான காலகட்டத்திற்கு நடைமுறைப்படுத்தப்பட்டன.","difficulty":"medium","topic":"பொது நிதி மற்றும் வரிகள்"},{"id":866,"subject":"gk","testNumber":9,"question":"'இந்தியப் பசுமைப் புரட்சியின் தந்தை' என அழைக்கப்படும் வேளாண் விஞ்ஞானி யார்?","options":["டாக்டர் சி. சுப்பிரமணியம்","டாக்டர் வர்கீஸ் குரியன்","டாக்டர் எம்.எஸ். சுவாமிநாதன்","டாக்டர் பி.பி. பால்"],"correctAnswer":2,"explanation":"அதிக விளைச்சல் தரும் குள்ள ரக விதைகள், ரசாயன உரங்கள் மற்றும் நவீன நீர்ப்பாசன முறைகளை இந்தியாவில் அறிமுகப்படுத்தி உணவு தானிய உற்பத்தியில் தன்னிறைவு அடையச் செய்த டாக்டர் எம்.எஸ். சுவாமிநாதன் 'இந்தியப் பசுமைப் புரட்சியின் தந்தை' எனப் போற்றப்படுகிறார்.","difficulty":"easy","topic":"வேளாண்மை"},{"id":867,"subject":"gk","testNumber":9,"question":"'உலகப் பசுமைப் புரட்சியின் தந்தை' எனப் போற்றப்படும் நோபல் பரிசு பெற்ற வேளாண் அறிஞர் யார்?","options":["வில்லியம் காட்","டாக்டர் நார்மன் போர்லாக்","லூயிஸ் பாஸ்டர்","கிரிகோர் மெண்டல்"],"correctAnswer":1,"explanation":"அமெரிக்க வேளாண் விஞ்ஞானியான டாக்டர் நார்மன் போர்லாக் அதிக மகசூல் தரும் மெக்சிகன் குள்ள ரக கோதுமையை உருவாக்கியதற்காக 'உலகப் பசுமைப் புரட்சியின் தந்தை' என அழைக்கப்படுகிறார். இவர் 1970ஆம் ஆண்டு அமைதிக்கான நோபல் பரிசைப் பெற்றார்.","difficulty":"easy","topic":"வேளாண்மை"},{"id":868,"subject":"gk","testNumber":9,"question":"இந்தியாவில் 1960களின் பிற்பகுதியில் தொடங்கப்பட்ட பசுமைப் புரட்சியால் மிக அதிக அளவில் உற்பத்தி உயர்ந்த உணவுப் பயிர்கள் எவை?","options":["தேயிலை மற்றும் காபி","பருப்பு வகைகள் மற்றும் எண்ணெய் வித்துகள்","பருத்தி மற்றும் சணல்","கோதுமை மற்றும் நெல்"],"correctAnswer":3,"explanation":"பசுமைப் புரட்சி முதன்மையாகக் கோதுமை மற்றும் நெல் ஆகிய தானியப் பயிர்களில் மிகப்பெரிய உற்பத்திப் பெருக்கத்தை ஏற்படுத்தியது. குறிப்பாகப் பஞ்சாப், ஹரியானா மற்றும் மேற்கு உத்தரப் பிரதேசம் ஆகிய மாநிலங்களில் கோதுமை உற்பத்தி பன்மடங்கு அதிகரித்தது.","difficulty":"easy","topic":"வேளாண்மை"},{"id":869,"subject":"gk","testNumber":9,"question":"இந்தியாவில் பால் உற்பத்தியைப் பெருக்கிய 'வெண்மைப் புரட்சி' (ஆபரேஷன் ஃப்ளட்) திட்டத்தின் தந்தை என அழைக்கப்படுபவர் யார்?","options":["சாம் பிட்ரோடா","டாக்டர் வர்கீஸ் குரியன்","டாக்டர் ஹிராலால் சவுத்ரி","டாக்டர் எம்.எஸ். சுவாமிநாதன்"],"correctAnswer":1,"explanation":"குஜராத்தின் அமுல் கூட்டுறவுப் பால் பண்ணை மாதிரியை நாடு முழுவதும் விரிவுபடுத்தி 1970இல் 'ஆபரேஷன் ஃப்ளட்' திட்டத்தைத் தொடங்கிய டாக்டர் வர்கீஸ் குரியன் 'இந்திய வெண்மைப் புரட்சியின் தந்தை' மற்றும் 'இந்தியாவின் பால் மனிதர்' என அழைக்கப்படுகிறார்.","difficulty":"easy","topic":"வேளாண்மை"},{"id":870,"subject":"gk","testNumber":9,"question":"கீழ்க்கண்ட வேளாண் புரட்சிகளும் அவற்றோடு தொடர்புடைய உற்பத்திப் பொருள்களும் கொடுக்கப்பட்டுள்ளன. அவற்றுள் தவறாகப் பொருந்தியுள்ள இணை எது?","options":["வெள்ளிப் புரட்சி – உரங்கள்","பொன் புரட்சி – பழங்கள் மற்றும் தேன் உற்பத்தி","நீலப் புரட்சி – மீன் உற்பத்தி","மஞ்சள் புரட்சி – எண்ணெய் வித்துகள்"],"correctAnswer":0,"explanation":"வெள்ளிப் புரட்சி என்பது முட்டை மற்றும் கோழிப் பண்ணை உற்பத்தியுடன் தொடர்புடையது; உரங்கள் உற்பத்தியுடன் தொடர்புடையது 'சாம்பல் புரட்சி' (Grey Revolution) ஆகும். மற்ற மூன்றும் (நீலப் புரட்சி – மீன், மஞ்சள் புரட்சி – எண்ணெய் வித்துகள், பொன் புரட்சி – பழங்கள், தேன் மற்றும் தோட்டக்கலை) சரியாகப் பொருந்தியுள்ளன.","difficulty":"medium","topic":"வேளாண்மை"},{"id":871,"subject":"gk","testNumber":9,"question":"சுதந்திரத்திற்குப் பின் இந்தியாவில் மேற்கொள்ளப்பட்ட நிலச் சீர்திருத்த நடவடிக்கைகளின் முதன்மை நோக்கமாக ஒழிக்கப்பட்ட இடைத்தரகர் நிலவுடைமை முறை எது?","options":["நவீன இயந்திர வேளாண்மை","ஒப்பந்த வேளாண்மை முறை","ஜமீன்தாரி முறை","கூட்டுறவு வேளாண்மை முறை"],"correctAnswer":2,"explanation":"'உழுபவனுக்கே நிலம் சொந்தம்' என்ற நோக்கத்துடன் சுதந்திரத்திற்குப் பின் மேற்கொள்ளப்பட்ட நிலச் சீர்திருத்தங்களில் ஜமீன்தாரி உள்ளிட்ட இடைத்தரகர் முறை ஒழிப்பு, குத்தகைச் சீர்திருத்தம் மற்றும் நில உச்சவரம்புச் சட்டம் ஆகியவை முக்கிய நடவடிக்கைகள் ஆகும்.","difficulty":"medium","topic":"வேளாண்மை"},{"id":872,"subject":"gk","testNumber":9,"question":"விவசாயிகளின் நலனைப் பாதுகாக்க வேளாண் விளைபொருள்களுக்குக் 'குறைந்தபட்ச ஆதரவு விலையை' (MSP) இந்திய அரசுக்குப் பரிந்துரை செய்யும் அமைப்பு எது?","options":["இந்திய உணவுக் கழகம் (FCI)","நிதி ஆயோக்","நபார்டு வங்கி (NABARD)","வேளாண் செலவு மற்றும் விலை ஆணையம் (CACP)"],"correctAnswer":3,"explanation":"வேளாண் செலவு மற்றும் விலை ஆணையத்தின் (Commission for Agricultural Costs and Prices - CACP) பரிந்துரையின் அடிப்படையில் மத்திய அரசு விதைப்புக் காலத்திற்கு முன்பே முக்கியப் பயிர்களுக்குக் குறைந்தபட்ச ஆதரவு விலையை (MSP) அறிவிக்கிறது.","difficulty":"hard","topic":"வேளாண்மை"},{"id":873,"subject":"gk","testNumber":9,"question":"இந்திய வேளாண்மைத் துறையில் தேவைக்கு அதிகமான தொழிலாளர்கள் ஈடுபட்டு, கூடுதல் தொழிலாளர்களின் இறுதிநிலை உற்பத்தித்திறன் பூஜ்ஜியமாக இருக்கும் நிலை எவ்வாறு அழைக்கப்படுகிறது?","options":["மறைமுக வேலைவாய்ப்பின்மை","பிறழ்ச்சி வேலைவாய்ப்பின்மை","சுழற்சி வேலைவாய்ப்பின்மை","அமைப்பு சார்ந்த வேலைவாய்ப்பின்மை"],"correctAnswer":0,"explanation":"ஒரு குறிப்பிட்ட வேலையில் தேவைக்கு அதிகமானவர்கள் பணியாற்றுவதும், அவர்களில் சிலரை நீக்கினாலும் மொத்த உற்பத்தி குறையாமல் இருப்பதும் 'மறைமுக வேலைவாய்ப்பின்மை' (Disguised Unemployment) எனப்படும். இது இந்திய வேளாண்மைத் துறையில் பரவலாகக் காணப்படுகிறது.","difficulty":"medium","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":874,"subject":"gk","testNumber":9,"question":"வேளாண்மை மற்றும் சர்க்கரை ஆலைகள் போன்ற தொழில்களில் ஆண்டின் சில மாதங்களில் மட்டும் வேலை கிடைத்து, எஞ்சிய மாதங்களில் வேலையின்றி இருக்கும் நிலை எது?","options":["தொழில்நுட்ப வேலைவாய்ப்பின்மை","பருவகால வேலைவாய்ப்பின்மை","நாள்பட்ட வேலைவாய்ப்பின்மை","கற்றோர் வேலைவாய்ப்பின்மை"],"correctAnswer":1,"explanation":"விதைப்பு மற்றும் அறுவடை போன்ற குறிப்பிட்ட பருவங்களில் மட்டும் வேலை கிடைத்து, மற்ற மாதங்களில் வேலை கிடைக்காத நிலை 'பருவகால வேலைவாய்ப்பின்மை' (Seasonal Unemployment) எனப்படும். இந்திய கிராமப்புறங்களில் இது அதிகமாகக் காணப்படுகிறது.","difficulty":"easy","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":875,"subject":"gk","testNumber":9,"question":"இந்தியாவில் வறுமைக் கோட்டைக் கணக்கிடுவதற்குக் கிராமப்புறத்திற்கு 2,400 கலோரி மற்றும் நகர்ப்புறத்திற்கு 2,100 கலோரி உணவை அளவுகோலாக 1979ஆம் ஆண்டு பரிந்துரைத்த குழு எது?","options":["சி. ரங்கராஜன் குழு","மல்ஹோத்ரா குழு","ஒய்.கே. அலக் குழு","சர்க்காரியா குழு"],"correctAnswer":2,"explanation":"திட்டக் குழுவால் நியமிக்கப்பட்ட ஒய்.கே. அலக் குழு (1979) ஊட்டச்சத்துத் தேவையின் அடிப்படையில் கிராமப்புற நபருக்கு நாளொன்றுக்கு 2,400 கலோரியும், நகர்ப்புற நபருக்கு 2,100 கலோரியும் கிடைப்பதற்கான செலவை வறுமைக் கோடாகப் பரிந்துரைத்தது.","difficulty":"hard","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":876,"subject":"gk","testNumber":9,"question":"2009ஆம் ஆண்டு வறுமைக் கோட்டை மறுவரையறை செய்து, உணவுடன் கல்வி மற்றும் சுகாதாரச் செலவுகளையும் சேர்த்து நுகர்வுச் செலவு முறையைப் பரிந்துரைத்த குழு எது?","options":["கேல்கர் குழு","சுரேஷ் டெண்டுல்கர் குழு","வி.எம். தண்டேகர் குழு","எல்.கே. ஜா குழு"],"correctAnswer":1,"explanation":"சுரேஷ் டெண்டுல்கர் குழு 2009ஆம் ஆண்டு தனது அறிக்கையில் கலோரி அடிப்படையிலான பழைய முறையிலிருந்து விலகி, உணவு, கல்வி மற்றும் சுகாதாரம் உள்ளிட்ட அடிப்படை நுகர்வுச் செலவுகளை உள்ளடக்கிய புதிய வறுமைக் கோட்டு அளவீட்டைப் பரிந்துரைத்தது.","difficulty":"hard","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":877,"subject":"gk","testNumber":9,"question":"மகாத்மா காந்தி தேசிய ஊரக வேலை உறுதிச் சட்டம் (MGNREGA) இந்திய நாடாளுமன்றத்தால் எந்த ஆண்டு இயற்றப்பட்டது?","options":["2009","2001","2005","2003"],"correctAnswer":2,"explanation":"தேசிய ஊரக வேலை உறுதிச் சட்டம் (NREGA) 2005ஆம் ஆண்டு இயற்றப்பட்டு, பிப்ரவரி 2, 2006 அன்று நடைமுறைக்கு வந்தது. 2009ஆம் ஆண்டு இதன் பெயர் 'மகாத்மா காந்தி தேசிய ஊரக வேலை உறுதிச் சட்டம்' (MGNREGA) என மாற்றப்பட்டது.","difficulty":"easy","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":878,"subject":"gk","testNumber":9,"question":"மகாத்மா காந்தி தேசிய ஊரக வேலை உறுதித் திட்டத்தின் (MGNREGA) கீழ் ஒரு நிதியாண்டில் ஒவ்வொரு கிராமப்புறக் குடும்பத்திற்கும் குறைந்தபட்சம் எத்தனை நாட்கள் வேலைவாய்ப்பு உறுதி செய்யப்படுகிறது?","options":["150 நாட்கள்","200 நாட்கள்","100 நாட்கள்","50 நாட்கள்"],"correctAnswer":2,"explanation":"MGNREGA சட்டத்தின் கீழ், உடல் உழைப்பு செய்ய விருப்பமுள்ள வயது வந்த உறுப்பினர்களைக் கொண்ட ஒவ்வொரு கிராமப்புறக் குடும்பத்திற்கும் ஒரு நிதியாண்டில் குறைந்தபட்சம் 100 நாட்கள் உறுதி செய்யப்பட்ட ஊதிய வேலைவாய்ப்பு சட்டப்பூர்வ உரிமையாக வழங்கப்படுகிறது.","difficulty":"easy","topic":"வேலைவாய்ப்பின்மை மற்றும் வறுமை"},{"id":879,"subject":"gk","testNumber":9,"question":"இந்தியாவில் பிற மாநிலங்கள் இலக்கு பொது விநியோக முறையைப் பின்பற்றும் நிலையில், 'அனைவருக்குமான பொது விநியோக முறையை' (Universal PDS) நடைமுறைப்படுத்தும் மாநிலம் எது?","options":["மகாராஷ்டிரா","தமிழ்நாடு","பீகார்","குஜராத்"],"correctAnswer":1,"explanation":"தமிழ்நாடு அனைவருக்குமான பொது விநியோக முறையை (Universal Public Distribution System) வெற்றிகரமாகச் செயல்படுத்துகிறது. இதன் மூலம் குடும்ப அட்டை வைத்திருக்கும் அனைத்துக் குடும்பங்களுக்கும் நியாய விலைக் கடைகள் வழியாக அத்தியாவசிய உணவுப் பொருள்கள் வழங்கப்படுகின்றன.","difficulty":"medium","topic":"உணவுப் பாதுகாப்பு"},{"id":880,"subject":"gk","testNumber":9,"question":"இந்தியாவில் 'தேசிய உணவுப் பாதுகாப்புச் சட்டம்' (NFSA) எந்த ஆண்டு நாடாளுமன்றத்தில் இயற்றப்பட்டது?","options":["2016","2013","2005","2010"],"correctAnswer":1,"explanation":"இந்திய மக்களுக்கு மானிய விலையில் தரமான உணவு தானியங்களைச் சட்டப்பூர்வ உரிமையாக வழங்கும் 'தேசிய உணவுப் பாதுகாப்புச் சட்டம்' (National Food Security Act) 2013ஆம் ஆண்டு இயற்றப்பட்டது. இச்சட்டம் தமிழ்நாட்டில் நவம்பர் 1, 2016 அன்று நடைமுறைப்படுத்தப்பட்டது.","difficulty":"medium","topic":"உணவுப் பாதுகாப்பு"},{"id":881,"subject":"gk","testNumber":9,"question":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி இந்தியாவில் மிக அதிக எழுத்தறிவு விகிதம் கொண்ட மாநிலம் எது?","options":["கோவா","மகாராஷ்டிரா","கேரளா","தமிழ்நாடு"],"correctAnswer":2,"explanation":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி கேரளா 94% எழுத்தறிவு விகிதத்துடன் இந்தியாவில் முதலிடத்தில் உள்ளது. இந்தியாவின் ஒட்டுமொத்த எழுத்தறிவு விகிதம் 74.04% ஆகவும், பீகார் மிகக் குறைந்த எழுத்தறிவு விகிதம் கொண்ட மாநிலமாகவும் பதிவாகியது.","difficulty":"easy","topic":"மக்கள் தொகைக் கணக்கெடுப்பு 2011"},{"id":882,"subject":"gk","testNumber":9,"question":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி இந்தியாவின் மக்கள் தொகை அடர்த்தி ஒரு சதுர கிலோமீட்டருக்கு எவ்வளவு?","options":["555 நபர்கள்","382 நபர்கள்","324 நபர்கள்","450 நபர்கள்"],"correctAnswer":1,"explanation":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி இந்தியாவின் சராசரி மக்கள் தொகை அடர்த்தி ஒரு சதுர கிலோமீட்டருக்கு 382 நபர்கள் ஆகும். மாநிலங்களில் பீகார் மிக அதிக அடர்த்தியும் (1,106), அருணாச்சலப் பிரதேசம் மிகக் குறைந்த அடர்த்தியும் (17) கொண்டிருந்தன.","difficulty":"medium","topic":"மக்கள் தொகைக் கணக்கெடுப்பு 2011"},{"id":883,"subject":"gk","testNumber":9,"question":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி தமிழ்நாட்டின் மக்கள் தொகை அடர்த்தி ஒரு சதுர கிலோமீட்டருக்கு எவ்வளவு?","options":["555 நபர்கள்","382 நபர்கள்","620 நபர்கள்","480 நபர்கள்"],"correctAnswer":0,"explanation":"2011ஆம் ஆண்டு மக்கள் தொகைக் கணக்கெடுப்பின்படி தமிழ்நாட்டின் மக்கள் தொகை அடர்த்தி ஒரு சதுர கிலோமீட்டருக்கு 555 நபர்கள் ஆகும். இது 2001ஆம் ஆண்டில் 480 நபர்களாக இருந்தது; மேலும் இது தேசிய சராசரியான 382ஐ விட அதிகமாகும்.","difficulty":"medium","topic":"மக்கள் தொகைக் கணக்கெடுப்பு 2011"},{"id":884,"subject":"gk","testNumber":9,"question":"இந்திய மக்கள் தொகை வரலாற்றில் 'பெரும் பிரிவினை ஆண்டு' (Year of Great Divide) என அழைக்கப்படும் ஆண்டு எது?","options":["1921","1901","1971","1951"],"correctAnswer":0,"explanation":"1911–1921 பத்தாண்டில் பஞ்சம் மற்றும் கொள்ளை நோய்களால் இந்திய மக்கள் தொகை எதிர்மறை வளர்ச்சியைப் பதிவு செய்தது. ஆனால் 1921ஆம் ஆண்டிற்குப் பிறகு மக்கள் தொகை தொடர்ந்து உயர்ந்து கொண்டே சென்றதால் 1921 'பெரும் பிரிவினை ஆண்டு' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"மக்கள் தொகைக் கணக்கெடுப்பு 2011"},{"id":885,"subject":"gk","testNumber":9,"question":"1944ஆம் ஆண்டு நடைபெற்ற 'பிரெட்டன் வுட்ஸ்' (Bretton Woods) மாநாட்டின் விளைவாக உருவான 'இரட்டை அமைப்புகள்' எவை?","options":["உலக வங்கி (IBRD) மற்றும் பன்னாட்டுப் பண நிதியம் (IMF)","ஆசிய வளர்ச்சி வங்கி மற்றும் பிரிக்ஸ் வங்கி","உலக வர்த்தக அமைப்பு மற்றும் ஐக்கிய நாடுகள் சபை","யுனெஸ்கோ மற்றும் உலக சுகாதார அமைப்பு"],"correctAnswer":0,"explanation":"1944ஆம் ஆண்டு அமெரிக்காவின் பிரெட்டன் வுட்ஸ் மாநாட்டின் முடிவாக பன்னாட்டு மறுசீரமைப்பு மற்றும் வளர்ச்சி வங்கி (உலக வங்கி - IBRD) மற்றும் பன்னாட்டுப் பண நிதியம் (IMF) ஆகிய இரு அமைப்புகள் உருவாக்கப்பட்டன. இவை 'பிரெட்டன் வுட்ஸ் இரட்டையர்கள்' எனப்படுகின்றன; இவற்றின் தலைமையகம் வாஷிங்டன் டி.சி.யில் உள்ளது.","difficulty":"medium","topic":"பன்னாட்டுப் பொருளாதார அமைப்புகள்"},{"id":886,"subject":"gk","testNumber":9,"question":"காட் (GATT) ஒப்பந்தத்திற்கு மாற்றாக 'உலக வர்த்தக அமைப்பு' (WTO) எப்போது தொடங்கப்பட்டது மற்றும் இதன் தலைமையகம் எங்கு உள்ளது?","options":["ஏப்ரல் 1, 1991; நியூயார்க்","ஜூலை 1, 1994; பாரிஸ்","ஜனவரி 1, 1995; ஜெனீவா","ஜனவரி 1, 1995; வாஷிங்டன் டி.சி."],"correctAnswer":2,"explanation":"உருகுவே சுற்றுப் பேச்சுவார்த்தையின் முடிவாக, காட் (GATT) ஒப்பந்தத்திற்கு மாற்றாக ஜனவரி 1, 1995 அன்று உலக வர்த்தக அமைப்பு (WTO) தொடங்கப்பட்டது. சுவிட்சர்லாந்தின் ஜெனீவா நகரில் இதன் தலைமையகம் அமைந்துள்ளது.","difficulty":"medium","topic":"பன்னாட்டுப் பொருளாதார அமைப்புகள்"},{"id":887,"subject":"gk","testNumber":9,"question":"மோட்டார் வாகனங்கள் மற்றும் வாகன உதிரிபாகங்கள் உற்பத்தியில் முன்னணி வகிப்பதால் 'ஆசியாவின் டெட்ராய்ட்' என அழைக்கப்படும் தமிழ்நாட்டின் நகரம் எது?","options":["சென்னை","திருச்சிராப்பள்ளி","கோயம்புத்தூர்","சேலம்"],"correctAnswer":0,"explanation":"பன்னாட்டு மற்றும் உள்நாட்டு முன்னணி மோட்டார் வாகனத் தொழிற்சாலைகள் அதிக அளவில் அமைந்துள்ளதால் சென்னை 'ஆசியாவின் டெட்ராய்ட்' (Detroit of Asia) என அழைக்கப்படுகிறது. இந்தியாவின் வாகன ஏற்றுமதியில் சென்னை பெரும் பங்கு வகிக்கிறது.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":888,"subject":"gk","testNumber":9,"question":"பருத்தி நூற்பாலைகள், நெசவுத் தொழில் மற்றும் விசைப்பம்பு உற்பத்திக்குப் புகழ்பெற்று 'தென்னிந்தியாவின் மான்செஸ்டர்' என அழைக்கப்படும் நகரம் எது?","options":["திருநெல்வேலி","கோயம்புத்தூர்","ஈரோடு","மதுரை"],"correctAnswer":1,"explanation":"பருத்தி நூற்பாலைகள், ஜவுளித் தொழில், பொறியியல் மற்றும் மின்மோட்டார் பம்புசெட் உற்பத்தியில் சிறந்து விளங்குவதால் கோயம்புத்தூர் 'தென்னிந்தியாவின் மான்செஸ்டர்' மற்றும் 'பம்பு நகரம்' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":889,"subject":"gk","testNumber":9,"question":"இந்தியாவின் 'பின்னலாடைத் தலைநகரம்' மற்றும் 'டாலர் நகரம்' எனப் புகழப்படும் தமிழ்நாட்டின் தொழில் நகரம் எது?","options":["திருப்பூர்","சேலம்","காஞ்சிபுரம்","கரூர்"],"correctAnswer":0,"explanation":"பருத்தி பின்னலாடைகள் உற்பத்தி மற்றும் வெளிநாட்டு ஏற்றுமதியில் நாட்டிலேயே முதன்மை மையமாகத் திகழும் திருப்பூர் 'இந்தியாவின் பின்னலாடைத் தலைநகரம்' (Knitwear Capital of India) மற்றும் 'டாலர் நகரம்' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":890,"subject":"gk","testNumber":9,"question":"பட்டாசு, தீப்பெட்டி மற்றும் அச்சுத் தொழில்களில் இந்திய அளவில் முதலிடம் வகிப்பதால் 'குட்டி ஜப்பான்' (Little Japan) என அழைக்கப்படும் தமிழ்நாட்டின் நகரம் எது?","options":["சிவகாசி","திண்டுக்கல்","விருதுநகர்","தூத்துக்குடி"],"correctAnswer":0,"explanation":"விருதுநகர் மாவட்டத்தில் உள்ள சிவகாசி நகரம் இந்தியாவின் பெரும்பாலான பட்டாசு, தீப்பெட்டி மற்றும் அச்சுப் பொருள்களை உற்பத்தி செய்கிறது. ஜவஹர்லால் நேரு சிவகாசியின் தொழில் வளர்ச்சியைப் பாராட்டி 'குட்டி ஜப்பான்' என அழைத்தார்.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":891,"subject":"gk","testNumber":9,"question":"தமிழ்நாட்டின் 'மஞ்சள் நகரம்' என்றும், விசைத்தறி மற்றும் ஜவுளி வணிகத்தின் முக்கிய மையமாகவும் விளங்கும் நகரம் எது?","options":["ஈரோடு","நாமக்கல்","தஞ்சாவூர்","சேலம்"],"correctAnswer":0,"explanation":"மஞ்சள் உற்பத்தி மற்றும் மஞ்சள் சந்தைக்கு உலகப் புகழ்பெற்ற ஈரோடு தமிழ்நாட்டின் 'மஞ்சள் நகரம்' என அழைக்கப்படுகிறது. ஈரோடு மஞ்சளுக்குப் புவிசார் குறியீடும் (GI Tag) வழங்கப்பட்டுள்ளது; மேலும் இது ஜவுளி மற்றும் கைத்தறித் தொழிலிலும் சிறந்து விளங்குகிறது.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":892,"subject":"gk","testNumber":9,"question":"வீட்டு உபயோக ஜவுளிப் பொருள்கள் (Home Textiles) ஏற்றுமதிக்கும், பேருந்து கூடு கட்டுமானத் தொழிலுக்கும் புகழ்பெற்ற தமிழ்நாட்டின் நகரம் எது?","options":["கோயம்புத்தூர்","நாமக்கல்","திருப்பூர்","கரூர்"],"correctAnswer":3,"explanation":"தமிழ்நாட்டின் கரூர் நகரம் படுக்கை விரிப்புகள், திரைச்சீலைகள், மேசை விரிப்புகள் போன்ற வீட்டு உபயோக ஜவுளிப் பொருள்கள் ஏற்றுமதிக்கும், தென்னிந்திய அளவில் பேருந்து கூடு கட்டுமானத் தொழிலுக்கும் (Bus Body Building) மிகவும் புகழ்பெற்றதாகும்.","difficulty":"medium","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":893,"subject":"gk","testNumber":9,"question":"இருசக்கர வாகனங்கள், வாகன உதிரிபாகங்கள் மற்றும் மின்னணுத் தொழில்களின் முக்கிய மையமாகவும் 'குட்டி இங்கிலாந்து' எனவும் அழைக்கப்படும் தமிழ்நாட்டின் நகரம் எது?","options":["ஆம்பூர்","ஓசூர்","ராணிப்பேட்டை","வேலூர்"],"correctAnswer":1,"explanation":"கிருஷ்ணகிரி மாவட்டத்தில் உள்ள ஓசூர் நகரம் பெங்களூருவிற்கு அருகில் அமைந்து, இருசக்கர வாகனங்கள், மோட்டார் வாகன உதிரிபாகங்கள், மின்னணுப் பொருள்கள் மற்றும் மலர் ஏற்றுமதியில் முன்னணித் தொழில் மையமாக விளங்குகிறது.","difficulty":"medium","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":894,"subject":"gk","testNumber":9,"question":"'தமிழ்நாட்டின் நுழைவாயில்' என அழைக்கப்படும் உப்பு உற்பத்தி, வேதிப்பொருள் தொழில் மற்றும் முக்கியத் துறைமுக நகரம் எது?","options":["நாகப்பட்டினம்","ராமேஸ்வரம்","தூத்துக்குடி","கடலூர்"],"correctAnswer":2,"explanation":"வ.உ.சிதம்பரனார் துறைமுகத்தைக் கொண்டுள்ள தூத்துக்குடி 'தமிழ்நாட்டின் நுழைவாயில்' மற்றும் 'முத்து நகரம்' என அழைக்கப்படுகிறது. இது தமிழ்நாட்டின் உப்பு உற்பத்தியில் முதலிடத்திலும், வேதிப்பொருள் மற்றும் அனல் மின்சார உற்பத்தியில் முக்கிய மையமாகவும் உள்ளது.","difficulty":"easy","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":895,"subject":"gk","testNumber":9,"question":"தமிழ்நாட்டில் பெரிய மற்றும் நடுத்தரத் தொழில் நிறுவனங்களை ஊக்குவிப்பதற்காக 'தமிழ்நாடு தொழில் வளர்ச்சிக் கழகம்' (TIDCO) எந்த ஆண்டு நிறுவப்பட்டது?","options":["1976","1949","1965","1971"],"correctAnswer":2,"explanation":"தமிழ்நாடு தொழில் வளர்ச்சிக் கழகம் (Tamil Nadu Industrial Development Corporation - TIDCO) 1965ஆம் ஆண்டு தமிழ்நாடு அரசால் நிறுவப்பட்டது. இது மாநிலத்தில் பெரிய மற்றும் நடுத்தரத் தொழில்களைக் கூட்டுத் துறை மற்றும் தனியார் பங்களிப்புடன் மேம்படுத்துகிறது.","difficulty":"medium","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":896,"subject":"gk","testNumber":9,"question":"தமிழ்நாட்டில் தொழில் பூங்காக்கள் மற்றும் தொழில் உள்கட்டமைப்புகளை உருவாக்கும் 'தமிழ்நாடு அரசு தொழில் முன்னேற்றக் கழகம்' (SIPCOT) எந்த ஆண்டு தொடங்கப்பட்டது?","options":["1970","1971","1965","1976"],"correctAnswer":1,"explanation":"தமிழ்நாடு அரசு தொழில் முன்னேற்றக் கழகம் (State Industries Promotion Corporation of Tamil Nadu - SIPCOT) 1971ஆம் ஆண்டு தொடங்கப்பட்டது. இது மாநிலம் முழுவதும் தொழில் வளாகங்கள் மற்றும் சிறப்புப் பொருளாதார மண்டலங்களை அமைத்துத் தொழில் வளர்ச்சியை ஊக்குவிக்கிறது.","difficulty":"medium","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":897,"subject":"gk","testNumber":9,"question":"அரியலூர் மற்றும் ஆலங்குளம் ஆகிய இடங்களில் அரசு சிமெண்ட் ஆலைகளை இயக்கும் 'தமிழ்நாடு சிமெண்ட் கழகம்' (TANCEM) எந்த ஆண்டு நிறுவப்பட்டது?","options":["1970","1976","1965","1980"],"correctAnswer":1,"explanation":"தமிழ்நாடு சிமெண்ட் கழகம் (Tamil Nadu Cements Corporation Limited - TANCEM) 1976ஆம் ஆண்டு நிறுவப்பட்டது. இது அரசு பொதுத்துறை நிறுவனமாக அரியலூர் மற்றும் விருதுநகர் மாவட்டத்தின் ஆலங்குளம் ஆகிய இடங்களில் சிமெண்ட் உற்பத்தி ஆலைகளை இயக்குகிறது.","difficulty":"hard","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":898,"subject":"gk","testNumber":9,"question":"தமிழ்நாட்டில் மகளிர் சுயஉதவிக் குழுக்கள் (SHGs) திட்டம் 1989ஆம் ஆண்டு முதன்முதலில் எந்த மாவட்டத்தில் தொடங்கப்பட்டது?","options":["மதுரை","சேலம்","தர்மபுரி","தஞ்சாவூர்"],"correctAnswer":2,"explanation":"தமிழ்நாட்டில் பெண்களின் சமூக மற்றும் பொருளாதார மேம்பாட்டிற்காக மகளிர் சுயஉதவிக் குழுக்கள் (Self Help Groups) திட்டம் பன்னாட்டு வேளாண் வளர்ச்சி நிதியத்தின் (IFAD) உதவியுடன் 1989ஆம் ஆண்டு முதன்முதலில் தர்மபுரி மாவட்டத்தில் தொடங்கப்பட்டது.","difficulty":"medium","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":899,"subject":"gk","testNumber":9,"question":"தமிழ்நாட்டில் மகளிர் சுயஉதவிக் குழுக்களை ஒருங்கிணைத்து 'மகளிர் திட்டத்தை' செயல்படுத்துவதற்காக 1983ஆம் ஆண்டு உருவாக்கப்பட்ட மாநில நிறுவனம் எது?","options":["தமிழ்நாடு மகளிர் மேம்பாட்டு நிறுவனம் (TNCDW)","தமிழ்நாடு தொழில் முதலீட்டுக் கழகம் (TIIC)","தமிழ்நாடு சிறுதொழில் வளர்ச்சிக் கழகம் (TANSIDCO)","தமிழ்நாடு கைத்தறி வளர்ச்சிக் கழகம்"],"correctAnswer":0,"explanation":"பெண்களின் சமூக-பொருளாதார அதிகாரமளிப்பை நோக்கமாகக் கொண்டு 1983ஆம் ஆண்டு தமிழ்நாடு மகளிர் மேம்பாட்டு நிறுவனம் (Tamil Nadu Corporation for Development of Women - TNCDW) நிறுவப்பட்டது. இதுவே மாநிலம் முழுவதும் மகளிர் சுயஉதவிக் குழுக்களை மேம்படுத்தும் முதன்மை அமைப்பாகும்.","difficulty":"hard","topic":"தமிழ்நாடு பொருளாதாரம்"},{"id":900,"subject":"gk","testNumber":9,"question":"இந்தியாவிலேயே முதன்முதலாக 1949ஆம் ஆண்டு தொடங்கப்பட்ட மாநில தொழில் நிதிக் கழகம் எது?","options":["தமிழ்நாடு அரசு தொழில் முன்னேற்றக் கழகம் (SIPCOT)","தமிழ்நாடு தொழில் வளர்ச்சிக் கழகம் (TIDCO)","தமிழ்நாடு சிறுதொழில் வளர்ச்சிக் கழகம் (TANSIDCO)","தமிழ்நாடு தொழில் முதலீட்டுக் கழகம் (TIIC)"],"correctAnswer":3,"explanation":"தமிழ்நாடு தொழில் முதலீட்டுக் கழகம் (Tamil Nadu Industrial Investment Corporation - TIIC) 1949ஆம் ஆண்டு தொடங்கப்பட்டது. இது இந்தியாவில் நிறுவப்பட்ட முதல் மாநில நிதிக் கழகமாகும்; இது குறு, சிறு மற்றும் நடுத்தரத் தொழில்களுக்குக் குறைந்த வட்டியில் கடன் உதவி வழங்குகிறது.","difficulty":"hard","topic":"தமிழ்நாடு பொருளாதாரம்"}]);
